public static int linearSearch(int[] arr, int target) {
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] == target) return i;
    }
    return -1;  // -1 means not found
}
// Worst case: O(n) — checks every element

// Searching for 42 in [3,7,12,24,42,57,68,85]:
// Step 1: mid = index 3 (value 24). 42 > 24 → search right half
// Step 2: mid = index 5 (value 57). 42 < 57 → search left half
// Step 3: mid = index 4 (value 42). Found! Return 4.
// 3 steps for 8 elements. 20 steps for 1,048,576 elements.

